import { l as uiText } from '../../../../src/i18n.js';
import {useEffect,useRef,useState} from 'react';
import {readOfd,renderPageToCanvas,getPageCount} from '@sharp9/ofdjs';
export default function OfdPreview({base}:{base:string}){
  const canvas=useRef<HTMLCanvasElement>(null);const [document,setDocument]=useState<any>(),[page,setPage]=useState(0),[error,setError]=useState(''),[busy,setBusy]=useState(true),[text,setText]=useState(''),[showText,setShowText]=useState(false);
  useEffect(()=>{if(!document)return;let disposed=false;window.dispatchEvent(new Event('moki:preview-location-changed'));const entry=document.document.pages.page[page],root=document.node.docBody.docRoot.split('/').slice(0,-1).join('/');void document.readFile([root,entry.baseLoc].filter(Boolean).join('/')).then((xml:string)=>{if(disposed)return;const parsed=new DOMParser().parseFromString(xml,'text/xml');setText([...parsed.getElementsByTagNameNS('*','TextCode')].map(n=>n.textContent).join('\n'))}).catch(()=>{if(!disposed)setText(uiText("本页文字层不可用，可框选画面协作"))});return()=>{disposed=true}},[document,page]);
  useEffect(()=>{const abort=new AbortController();let disposed=false;void(async()=>{try{const response=await fetch(base+'preview',{signal:abort.signal});if(!response.ok)throw Error(uiText("OFD 读取失败"));const data=await readOfd(await response.arrayBuffer());if(!disposed)setDocument(data)}catch(e){if(!disposed){setError(String(e));setBusy(false)}}})();return()=>{disposed=true;abort.abort()}},[base]);
  useEffect(()=>{if(!document||!canvas.current)return;let disposed=false;setBusy(true);const target=canvas.current;renderPageToCanvas(document,page,target,{dpi:97,scale:1.5}).then(()=>{if(!disposed)setBusy(false)}).catch((e:any)=>{if(!disposed){setError(String(e));setBusy(false)}});return()=>{disposed=true}},[document,page]);
  const count=document?getPageCount(document):0;
  const location=JSON.stringify({kind:'ofd',page:page+1,totalPages:count});
  return <><div className="library-extra-toolbar" data-moki-view-context={location}><button disabled={busy||page===0} onClick={()=>setPage(page-1)}>{uiText("上一页")}</button><span>{page+1} / {count||'…'}</span><button disabled={busy||page+1>=count} onClick={()=>setPage(page+1)}>{uiText("下一页")}</button><button aria-pressed={showText} onClick={()=>setShowText(!showText)}>{showText?uiText("查看页面"):uiText("选择文字")}</button><small>{uiText("OFD 内容预览；复杂路径与签章请以原应用为准")}</small></div><div className="library-extra-scroll" data-moki-location={location}>{error?<p role="alert">{error}</p>:null}{busy?<p role="status">{uiText("正在渲染…")}</p>:null}<canvas style={{display:showText?'none':undefined}} className="library-ofd-page" ref={canvas}/>{showText&&<pre data-moki-selection-text="ofd">{text}</pre>}</div></>;
}
